b.constraint('zoom_identity_conservation',['zoom_plan','graph_function'],'Bind parent function/graph, vector identity/interface, refinement function/graph, substituted graph identity and all selecting authority references. Reject drift in any bound identity. Preserve parent input/output interface and publish the plan as declaration data.',[(11,27,32)])
b.constraint('foldback_parent_reassessment',['recursive_foldback'],'Declare rebind mode, exactly one nonempty binding and mandatory parent re-evaluation. Child completion supplies rebind input, not certification or evaluator bypass. Extra attributes are inert unless an owning requirement admits their semantics.',[(11,34,38)],exceptions=['An owning requirement may admit semantics for extra foldback attributes.'])
b.constraint('typed_wiring_admission',['typed_wiring'],'Each wiring names the left carried/provided node, right required node and one published node-type reference. Both satisfy the same type without weakening schema, Markov or AssetSurface law. Missing nodes, unknown/non-node-type references, incompatibility and empty wiring fail before composition.',[(11,40,45)])
b.constraint('typed_wiring_pure_result',['typed_wiring','graph_function'],'Success yields ordinary GraphFunction composition after replacing only the declared right requirement with its satisfying left carried node. It adds no coercion, rival edge, runtime router or second type system.',[(11,47,51)])
b.constraint('refinement_native_and_raw_admission',['zoom_plan','recursive_foldback','typed_wiring'],'Published tenants expose typed zoom/foldback/wiring interfaces plus raw admission and semantic diagnostics. Native types enforce everything expressible; malformed or unresolved serialized GTL fails admission/validation before HoG traversal. GTL owns declaration/pure construction, HoG direct traversal, ABG runtime frames/lineage/foldback/parent results/events/replay/closure. Product-local dispatch/vector classification is outside this capability.',[(11,53,58),(12,62,66)])
